components.css:
.ds-pilot-section{font-family:var(--font,'DM Sans',sans-serif);color:var(--ink,#191b1d);--ink:#191b1d;--muted:#62666b;--purple:#5758db;--purple-soft:#efefff}.ds-pilot-section form{background:#f6f5fa;border:1px solid #e0dfe9;border-radius:7px}.ds-pilot-section label{display:block}.ds-pilot-section select{background:#fff;color:#2a2d33;border:1px solid #cfcfdc}.ds-pilot-section .ds-button{font:inherit;display:inline-flex;align-items:center;border:1px solid transparent;padding:10px 13px;border-radius:0}.ds-icon{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.ds-pilot-section select:focus-visible,.ds-pilot-section input:focus-visible{outline:3px solid var(--purple);outline-offset:5px}
.ds-pilot-section{grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);align-items:start}
.ds-pilot-section>div{padding-top:20px}
.ds-pilot-section form{min-width:0;padding:30px}
.ds-pilot-field,.ds-pilot-section fieldset{margin:0 0 26px}
.ds-pilot-section fieldset{padding:0;border:0;min-width:0}
.ds-pilot-section label,.ds-pilot-section legend{font-size:14px;font-weight:500;color:var(--ink)}
.ds-pilot-section legend{padding:0;margin-bottom:12px}
.ds-pilot-section label[for=ds-team-type]{margin-bottom:10px}
.ds-select-wrap{position:relative}
.ds-pilot-section select{appearance:none;width:100%;height:52px;padding:12px 44px 12px 14px;margin:0;font:inherit;font-size:16px;border-radius:4px;cursor:pointer}
.ds-pilot-section select:invalid{color:var(--muted)}
.ds-select-wrap>svg{position:absolute;right:16px;top:18px;width:16px;height:16px;fill:none;stroke:var(--ink);stroke-width:1.5;pointer-events:none}
.ds-pilot-section .ds-focus-choice{display:flex;align-items:center;gap:12px;margin:0;padding:14px 12px;border:1px solid transparent;border-bottom-color:#dedde7;cursor:pointer;border-radius:4px}
.ds-pilot-section .ds-focus-choice:last-child{border-bottom-color:transparent}
.ds-pilot-section .ds-focus-choice:hover{background:#efedf7}
.ds-pilot-section .ds-focus-choice:has(input:checked){border-color:#b6b3ee;background:var(--purple-soft)}
.ds-focus-choice input{flex:0 0 auto;width:18px;height:18px;margin:0;accent-color:var(--purple)}
.ds-focus-choice strong{display:block;font-size:14px;font-weight:500;line-height:1.5}
.ds-focus-choice small{display:block;font-size:12px;font-weight:400;line-height:1.6;color:#565b68;margin-top:3px}
.ds-pilot-section .ds-field-hint{font-size:12px;line-height:1.6;color:var(--muted);margin:-5px 0 12px}
.ds-location-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.ds-pilot-section .ds-location-options label{position:relative;margin:0;cursor:pointer}
.ds-location-options input{position:absolute;opacity:0;width:1px;height:1px}
.ds-location-options span{display:flex;align-items:center;justify-content:center;min-height:48px;border:1px solid #cfcfdc;border-radius:4px;background:#fff;font-size:15px;font-variant-numeric:tabular-nums}
.ds-location-options input:checked+span{border-color:var(--purple);background:var(--purple-soft);color:var(--purple);box-shadow:inset 0 0 0 1px var(--purple)}
.ds-location-options label:hover span{border-color:var(--purple)}
.ds-location-options input:focus-visible+span{outline:3px solid var(--purple);outline-offset:3px}
.ds-pilot-form-bottom{display:block}
.ds-pilot-form-bottom .ds-button{width:100%;min-height:48px;font-size:14px;justify-content:center;gap:12px}
.ds-pilot-form-bottom .ds-button:disabled{opacity:1;background:#dedce8;color:#555367;cursor:not-allowed;transform:none}
.ds-pilot-section #ds-pilot-feedback{font-size:12px;line-height:1.65;margin:12px 0 0;color:#565b68}
@media(max-width:800px){.ds-pilot-section{grid-template-columns:1fr;gap:25px}.ds-pilot-section>div{padding-top:0}.ds-pilot-section>div>p{max-width:480px}.ds-pilot-section form{max-width:600px;width:100%}}
@media(max-width:600px){.ds-pilot-section form{padding:20px 16px;margin-top:28px}.ds-pilot-section .ds-focus-choice{padding:13px 9px;gap:10px}.ds-location-options{gap:6px}}
.ds-pilot-section{display:block}
